const testDV = DataViewBuilder.relational([{source:'A',target:'B',weight:5},{source:'B',target:'C',weight:10}]);

function createVisual() {
  const opts = createConstructorOptions();
  const settings = new NetworkGraphSettings();
  settingsRef.current = settings;
  const visual = new NetworkGraphVisual(opts as never);
  return {
    visual,
    settings: settings as unknown as Record<string, unknown> & { cards: Array<Record<string, unknown>> },
    element: opts.element,
  };
}

